"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { cn } from "../lib/cn.js";

// Generated by shadcn (Base UI, Mira) and rewritten: a `sheet` with `--radius-field` (menus) and
// `--shadow-lift`, because it floats. It grows from its trigger over `--dur-quick` (transform and
// opacity only, M9) and only fades under reduced motion (M10).

export const Popover = PopoverPrimitive.Root;
export const PopoverTrigger = PopoverPrimitive.Trigger;
export const PopoverClose = PopoverPrimitive.Close;

export function PopoverContent({
  className,
  align = "start",
  side = "bottom",
  sideOffset = 6,
  ...props
}: PopoverPrimitive.Popup.Props &
  Pick<PopoverPrimitive.Positioner.Props, "align" | "side" | "sideOffset">) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner
        align={align}
        side={side}
        sideOffset={sideOffset}
        className="z-50"
      >
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          className={cn(
            "flex w-72 max-w-[calc(100vw-2*var(--space-gutter))] flex-col gap-2 rounded-field border border-rule bg-sheet p-4",
            "font-sans text-sm text-ink shadow-lift outline-none",
            "origin-(--transform-origin) transition-[opacity,scale] duration-(--dur-quick) ease-out",
            "data-starting-style:scale-[0.96] data-starting-style:opacity-0",
            "data-ending-style:scale-[0.96] data-ending-style:opacity-0",
            "motion-reduce:data-starting-style:scale-100 motion-reduce:data-ending-style:scale-100",
            typeof className === "string" ? className : undefined,
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

export function PopoverTitle({ className, ...props }: PopoverPrimitive.Title.Props) {
  return (
    <PopoverPrimitive.Title
      data-slot="popover-title"
      className={cn(
        "font-sans text-base font-medium text-ink",
        typeof className === "string" ? className : undefined,
      )}
      {...props}
    />
  );
}

export function PopoverDescription({ className, ...props }: PopoverPrimitive.Description.Props) {
  return (
    <PopoverPrimitive.Description
      data-slot="popover-description"
      className={cn("text-ink-soft", typeof className === "string" ? className : undefined)}
      {...props}
    />
  );
}
